using System;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.Rendering;
namespace BWVR {
public sealed partial class SocialMemory {public int bellVisits;}
public sealed partial class VillageWorship {
 float bellUntil;int bellJoined;bool[] bellActive,bellUsed;
 public bool CanInviteBell=>cathedral!=null&&world.Season.Cathedral.level>0&&!world.Season.paused&&!world.Season.Religion.fanatic&&world.Season.Hybrid.time>=world.Season.Religion.cooldownUntil&&world.Season.Hybrid.time>=bellUntil&&(bellActive==null||Array.TrueForAll(bellActive,b=>!b));
 public int BellParticipants=>bellJoined;
 public bool InviteBell(){EnsureSeason();if(!CanInviteBell)return false;bellUntil=world.Season.Hybrid.time+30;bellJoined=0;Array.Clear(bellUsed,0,bellUsed.Length);return true;}
 void ResetBellInvitation(){bellUntil=0;bellJoined=0;if(bellActive==null){bellActive=new bool[jobs.Length];bellUsed=new bool[jobs.Length];}else{Array.Clear(bellActive,0,bellActive.Length);Array.Clear(bellUsed,0,bellUsed.Length);}}
 bool BellEligible(int i)=>bellActive!=null&&!bellUsed[i]&&bellJoined<4&&world.Season.Hybrid.time<bellUntil&&world.Season.Hybrid.time>=world.Season.Religion.cooldownUntil&&jobs[i].GetComponent<VillagerSocial>().Memory.faith>=.25f&&Vector3.Distance(jobs[i].transform.position,cathedral.BellPosition)<=world.Navigation.Scale*160;
}
public sealed partial class VillageCathedral {
 VillageWorship bellWorship;Func<bool> bellInput;GameObject bellRoot,bellNav;Transform bellPivot;LineRenderer bellWave;Material bellWaveMaterial;Vector3 bellLastSite;bool bellLocated;float bellRangAt=-100,bellPlaceAt;
 public SpatialTarget BellTarget{get;private set;}
 public Vector3 BellPosition=>bellRoot!=null?bellRoot.transform.position:Entrance;
 public bool BellReady=>State.level>0&&bellLocated&&bellInput?.Invoke()==true&&!world.Season.paused&&!world.Season.Religion.fanatic&&world.Season.Hybrid.time>=State.nextBellAt&&bellWorship?.CanInviteBell==true;
 public void BindBell(VillageWorship worship,Func<bool> inputAllowed){bellWorship=worship;bellInput=inputAllowed;}
 void BuildBell(){bellRoot=new GameObject("Shrine gathering bell");bellRoot.transform.SetParent(transform,false);SourcedItemArt.Fit("SettlementProps/structure-floor",bellRoot.transform,"Bell timber base",new Vector3(0,.1f,0),new Vector3(4,.2f,2.5f));for(int i=0;i<2;i++)SourcedItemArt.Fit("SettlementProps/resource-planks",bellRoot.transform,"Bell timber upright "+i,new Vector3(i==0?-1.5f:1.5f,2.5f,0),new Vector3(.3f,5,.3f));SourcedItemArt.Fit("SettlementProps/resource-planks",bellRoot.transform,"Bell crossbar",new Vector3(0,5,0),new Vector3(3.5f,.3f,.4f));var pivot=new GameObject("Swinging CC0 bell");pivot.transform.SetParent(bellRoot.transform,false);bellPivot=pivot.transform;bellPivot.localPosition=new Vector3(0,4.7f,0);SourcedItemArt.Fit("Cathedrals/GatheringBell",bellPivot,"Quaternius gathering bell",new Vector3(0,-1.2f,0),new Vector3(2,2.4f,2));
  var hit=bellRoot.AddComponent<BoxCollider>();hit.center=new Vector3(0,2.6f,0);hit.size=new Vector3(4.5f,5.5f,3);BellTarget=bellRoot.AddComponent<SpatialTarget>();BellTarget.invoke=()=>TryRingBell();bellWaveMaterial=new Material(Resources.Load<Material>("ConstructionPreview"));var wave=new GameObject("Bell sound ripple");wave.transform.SetParent(bellRoot.transform,false);bellWave=wave.AddComponent<LineRenderer>();bellWave.sharedMaterial=bellWaveMaterial;bellWave.useWorldSpace=false;bellWave.loop=true;bellWave.positionCount=40;bellWave.shadowCastingMode=ShadowCastingMode.Off;bellWave.enabled=false;
  bellNav=new GameObject("Bell native navigation footprint");bellNav.transform.SetParent(transform,false);var obstacle=bellNav.AddComponent<NavMeshObstacle>();obstacle.shape=NavMeshObstacleShape.Box;obstacle.size=new Vector3(5,8,3.5f);obstacle.center=Vector3.up*3;obstacle.carving=true;bellNav.SetActive(false);bellRoot.SetActive(false);
 }
 void ResetBellPresentation(){bellLocated=bellLocated&&State.sited&&State.site==bellLastSite;bellRangAt=-100;bellPlaceAt=0;if(bellPivot!=null)bellPivot.localRotation=Quaternion.identity;if(bellWave!=null)bellWave.enabled=false;}
 bool FindBellPosition(out Vector3 at){var nav=world.Navigation;for(int i=0;i<18;i++){float side=i%2==0?1:-1;var desired=Entrance+Vector3.right*side*(22+i/6*6)*nav.Scale+Vector3.back*(i/2%3)*nav.Scale*6;if(!nav.Sample(desired,nav.villager,2,out at))continue;at=nav.ProjectFoot(at,nav.villager);bool blocked=false;foreach(var hit in Physics.OverlapBox(at+Vector3.up*nav.Scale*3,new Vector3(3,3,2)*nav.Scale,Quaternion.identity,~0,QueryTriggerInteraction.Ignore))if(hit.GetComponentInParent<IslandPlacementView>()!=null||hit.GetComponentInParent<VillageResources>()!=null||hit.GetComponentInParent<ConstructionSite>()!=null){blocked=true;break;}if(!blocked)return true;}at=default;return false;}
 void RefreshBell(){if(bellRoot==null)return;var nav=world.Navigation;if(State.level>0&&!bellLocated&&world.Season.Hybrid.time>=bellPlaceAt&&FindBellPosition(out var point)){bellLocated=true;bellLastSite=State.site;bellRoot.transform.position=point;bellRoot.transform.localScale=Vector3.one*nav.Scale;bellWave.widthMultiplier=nav.Scale*.12f;bellNav.transform.position=nav.ToNav(point);}if(State.level>0&&!bellLocated&&world.Season.Hybrid.time>=bellPlaceAt)bellPlaceAt=world.Season.Hybrid.time+3;bool visible=State.level>0&&bellLocated;bellRoot.SetActive(visible);if(bellNav.activeSelf!=visible){bellNav.SetActive(visible);nav.TreeObstacleChanged();}float t=world.Season.Hybrid.time-bellRangAt;bool ringing=visible&&t>=0&&t<2.5f;bellPivot.localRotation=ringing?Quaternion.Euler(0,0,Mathf.Sin(t*16)*22*Mathf.Exp(-t*1.2f)):Quaternion.identity;bellWave.enabled=ringing;if(ringing){for(int i=0;i<40;i++){float angle=i*Mathf.PI/20;float radius=2+t*4;bellWave.SetPosition(i,new Vector3(Mathf.Cos(angle)*radius,3,Mathf.Sin(angle)*radius));}bellWave.startColor=bellWave.endColor=new Color(1,.9f,.5f,(1-t/2.5f)*.7f);}}
 public bool TryRingBell(){EnsureSeason();RefreshBell();if(!BellReady||!bellWorship.InviteBell())return false;State.bellRings=Math.Min(1000000,State.bellRings+1);State.nextBellAt=world.Season.Hybrid.time+90;bellRangAt=world.Season.Hybrid.time;IslandAudio.Cue(IslandSound.Bell,BellPosition,GetEntityId().GetHashCode(),.9f);world.GetComponentInParent<QuestSlice>().GetComponentInChildren<CreatureHybrid>().Journal.Add(world.Season.Hybrid.time,"cathedral bell",CreatureAction.IdleOrObserve,"village","Nearby free believers may gather; attendance is voluntary");RefreshBell();return true;}
 void DisposeBell(){if(bellWaveMaterial!=null)Destroy(bellWaveMaterial);}
}
}
